                counts[val] = counts.get(val, 0) + 1

    if not counts:
        return [row[:] for row in grid]

    # Check for marker pattern (like 9 in Demo 1 - appears very few times)
    max_count = max(counts.values())
    # If only one color appears very few times (< 3), use cross pattern
